import sys
from math import gcd

def main():
    n, k = map(int, sys.stdin.read().split())
    if k == 0:
        if n == 1:
            print(1)
        else:
            print(" ".join(map(str, range(1, n + 1))))
    else:
        if n < 2:
            print(-1)
        else:
            found = False
            for i in range(1, 10**9):
                if gcd(i, i + k) == k:
                    seq = [i, i + k]
                    seq += list(range(1, n - 1)) if n > 2 else []
                    if len(set(seq)) == n:
                        found = True
                        print(" ".join(map(str, seq)))
                        break
            if not found:
                print(-1)

main()
